	var values;
	var mask;
	var x;
	var i;

	x = zeros( [ 2, 2 ], {
		'dtype': 'float64'
	});
	mask = zeros( [ 2, 2 ], {
		'dtype': 'float64'
	});
	values = [ '5', 5, NaN, true, false, null, void 0, [], {}, function noop() {} ];
	for ( i = 0; i < values.length; i++ ) {
		t.throws( badValue( values[ i ] ), TypeError, 'throws when provided '+values[ i ] );
	}
	t.end();

	function badValue( value ) {
		return function badValue() {
			mskmin( x, mask, value );
		};
	}
